TLM.f("Sancti/01-18r",{"officium":"S. Priscæ Virginis","rule":["vide C6;"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","from":{"Introitus":"Commune/C6","Lectio":"Commune/C6","Graduale":"Commune/C6","GradualeP":"Commune/C6","Tractus":"Commune/C6","Evangelium":"Commune/C6","Offertorium":"Commune/C6","Communio":"Commune/C6"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:46-47"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, qui beátæ Priscæ Vírginis et Mártyris tuæ natalítia cólimus; et ánnua sollemnitáte lætémur, et tantæ fídei proficiámus exémplo."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:1-8; 51:12"},{"k":"text","la":"Confitébor tibi, Dómine, Rex, et collaudábo te Deum, Salvatórem meum. Confitébor nómini tuo: quóniam adjútor et protéctor factus es mihi, et liberásti corpus meum a perditióne, a láqueo línguæ iníquæ et a lábiis operántium mendácium, et in conspéctu astántium factus es mihi adjutor. Et liberasti me secúndum multitúdinem misericórdiæ nóminis tui a rugiéntibus, præparátis ad escam, de mánibus quæréntium ánimam meam, et de portis tribulatiónum, quæ circumdedérunt me: a pressúra flammæ, quæ circúmdedit me, et in médio ignis non sum æstuáta: de altitúdine ventris inferi, et a lingua coinquináta, et a verbo mendácii, a rege iníquo, et a lingua injústa: laudábit usque ad mortem ánima mea Dóminum: quóniam éruis sustinéntes te, et líberas eos de mánibus géntium, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe corónam, quam tibi Dóminus præparávit in ætérnum: pro cujus amóre sánguinem tuum fudísti."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines illae, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"Offertorium":[{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hæc hóstia, quǽsumus, Dómine, quam Sanctórum tuórum natalítia recenséntes offérimus, et víncula nostræ pravitátis absólvat, et tuæ nobis misericórdiæ dona concíliet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:78; 118:80"},{"k":"text","la":"Confundántur supérbi, quia injúste iniquitátem fecérunt in me: ego autem in mandátis tuis exercébor, in tuis justificatiónibus, ut non confúndar. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine, salutáribus repléti mystériis: ut, cujus sollémnia celebrámus, ejus oratiónibus adjuvémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a3cd70566279b650":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da se mi koji slavimo rođendan blažene Priske tvoje djevice i mučenice, radujemo godišnjoj svečanosti i okoristimo primjerom tolike vjere.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemoigući Bože, da mi, koji svetkujemo rođeni dan blažene Priske, Tvoje djevice i mučenice, budemo radosni o njezinoj svetkovini i užnapredujemo primjerom tolike vjere, po G. n.","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"691263c95f640c88":{"t":"Ovaj prinos, molimo, Gospodine, koji prikazujemo sjećajući se rođendana tvojih svetih neka odriješi okove naše zloće i neka nam pribavi darove tvoga milosrđa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova žrtva, molimo, Gospodine, što je prinosimo sjećajući se rođenog dana Tvojih mučeinika, odriješila i okove naše zloće i pribavila nam darove Tvog milosrđa, po G. n.","knRef":"Kniewald 1942, str. 660–661 (snimka 331) (OCR)"},"16e02abf334ca508":{"t":"<i>Pomolimo se</i>.\nNasićeni spasonosnim tajnama molimo, Gospodine, da nas pomažu molitve onih kojih svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Na'hranjeni spasonosnim tajnama molimo. Gospodine, da nas pomognu molitve onih, kojih svetkovinu slavimo, po G. n.","knRef":"Kniewald 1942, str. 548–549 (snimka 275) (OCR)"}}});
